use std::{fs, hint::black_box, io::{BufWriter,Write},time::Instant};
fn run(data:&[u8]){let mut frames=0;let info=syom::decode_streaming(data,&syom::DecodeOptions::unbounded(),|f|{frames+=f.samples;black_box(f.planar);Ok(())}).unwrap();black_box((frames,info));}
fn main(){let a:Vec<String>=std::env::args().collect();let data=fs::read(&a[2]).unwrap();if a[1]=="dump"{let mut w=BufWriter::new(fs::File::create(&a[3]).unwrap());let mut callbacks=0;let mut samples=0;let info=syom::decode_streaming(&data,&syom::DecodeOptions::unbounded(),|f|{callbacks+=1;samples+=f.samples;w.write_all(&f.sample_rate.to_le_bytes()).unwrap();w.write_all(&(f.planar.len()as u64).to_le_bytes()).unwrap();w.write_all(&(f.samples as u64).to_le_bytes()).unwrap();for p in f.planar{w.write_all(&(p.len()as u64).to_le_bytes()).unwrap();for v in *p{w.write_all(&v.to_bits().to_le_bytes()).unwrap();}}Ok(())}).unwrap();w.flush().unwrap();println!("{{\"callbacks\":{callbacks},\"samples_per_channel\":{samples},\"sample_rate\":{}}}",info.sample_rate);return;}let mut ts=Vec::new();for i in 0..9{let start=Instant::now();run(&data);if i>=2{ts.push(start.elapsed().as_secs_f64()*1000.0);}}let raw=ts.iter().map(ToString::to_string).collect::<Vec<_>>().join(",");ts.sort_by(f64::total_cmp);println!("{{\"median_ms\":{},\"samples_ms\":[{raw}]}}",ts[ts.len()/2]);}
